CREATE TABLE IF NOT EXISTS arc_transfer_previews (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), to_address text NOT NULL, amount numeric(78,0) NOT NULL, fee_estimate numeric(78,0) NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS arc_transfers (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), preview_id uuid NOT NULL UNIQUE REFERENCES arc_transfer_previews(id), to_address text NOT NULL, amount numeric(78,0) NOT NULL, purpose text NOT NULL, status text NOT NULL CHECK(status IN ('reserved','submitted','confirmed','failed','unknown')), tx_hash text, error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX IF NOT EXISTS arc_transfers_user_window ON arc_transfers(user_id,created_at DESC);
